import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import {
  DecryptError,
  FormatError,
  RecoveryKeyError,
  WeakKdfError,
  decryptBlob,
  decryptPathFor,
  deriveKekPassphrase,
  deriveSubkeys,
  parseRecoveryKey,
  unhex,
  unwrap,
  uuidBytes,
} from './index';

// Negative vectors generated by the Go implementation
// (shared/go/vaultcrypto/negative_test.go). Every input must be rejected.
// "any" means both implementations reject but classify differently.

type Expect = 'decrypt' | 'format' | 'any';
interface Negative {
  blobs: {
    name: string;
    vault_id: string;
    file_id: string;
    vmk: string;
    blob: string;
    expect: Expect;
  }[];
  /** Opened as the token of file_id (default: the vector file) in vault_id. */
  paths: { name: string; vault_id: string; file_id?: string; token: string; expect: Expect }[];
  /** Opened as the envelope of vault_id and kind (defaults: the vector vault, "passphrase"). */
  wrap: {
    name: string;
    kek: string;
    wrapped: string;
    vault_id?: string;
    kind?: string;
    expect: Expect;
  }[];
  kdf: { name: string; kdf: { alg: string; t: number; m_kib: number; p: number; salt: string } }[];
  recovery: { name: string; text: string }[];
}

const root = '../../../shared/conformance/crypto/';
const read = (f: string): string =>
  readFileSync(fileURLToPath(new URL(root + f, import.meta.url)), 'utf8');
const neg = JSON.parse(read('negative-vectors.json')) as Negative;
const { vmk, file_id: vectorFile } = (
  JSON.parse(read('vectors.json')) as { subkeys: { vmk: string; file_id: string } }
).subkeys;
const VECTOR_VAULT = '0194f0a8-0000-7000-8000-00000000aaaa';

async function expectRejected(p: Promise<unknown>, expect_: Expect): Promise<void> {
  const err = await p.then(
    () => null,
    (e: unknown) => e,
  );
  expect(err, 'must be rejected').not.toBeNull();
  if (expect_ === 'decrypt') expect(err).toBeInstanceOf(DecryptError);
  if (expect_ === 'format') expect(err).toBeInstanceOf(FormatError);
}

describe('negative conformance vectors (generated by Go)', () => {
  it('has a non-trivial corpus', () => {
    expect(neg.blobs.length).toBeGreaterThanOrEqual(20);
  });

  it.each(neg.blobs.map((c) => [c.name, c] as const))('blob: %s', async (_n, c) => {
    const sk = await deriveSubkeys(unhex(c.vmk));
    await expectRejected(
      decryptBlob(sk, uuidBytes(c.vault_id), uuidBytes(c.file_id), unhex(c.blob)),
      c.expect,
    );
  });

  it.each(neg.paths.map((c) => [c.name, c] as const))('path: %s', async (_n, c) => {
    const sk = await deriveSubkeys(unhex(vmk));
    const file = uuidBytes(c.file_id ?? vectorFile);
    await expectRejected(decryptPathFor(sk, uuidBytes(c.vault_id), file, c.token), c.expect);
  });

  it.each(neg.wrap.map((c) => [c.name, c] as const))('wrap: %s', async (_n, c) => {
    await expectRejected(
      unwrap(
        unhex(c.kek),
        unhex(c.wrapped),
        uuidBytes(c.vault_id ?? VECTOR_VAULT),
        c.kind ?? 'passphrase',
      ),
      c.expect,
    );
  });

  it.each(neg.kdf.map((c) => [c.name, c] as const))('kdf: %s', async (_n, c) => {
    await expect(deriveKekPassphrase('passphrase', c.kdf)).rejects.toBeInstanceOf(WeakKdfError);
  });

  it.each(neg.recovery.map((c) => [c.name, c] as const))('recovery: %s', async (_n, c) => {
    await expect(parseRecoveryKey(c.text)).rejects.toBeInstanceOf(RecoveryKeyError);
  });
});
